  e=entries[ident];p=(indexp.parent/e['procedureFile']).resolve();d=cache.setdefault(str(p),read(p));ptr=e.get('procedureTextPointer',e['procedurePointer']);cardptr=e.get('wholeCardPointer',e['procedurePointer']);current.append({'spellId':ident,'completeIndexEntry':deepcopy(e),'source':bind(p),'procedurePointer':ptr,'wholeCardPointer':cardptr,'completeCurrentProcedure':deepcopy(at(d,ptr)),'completeCurrentCard':deepcopy(at(d,cardptr)),'completeSharedRules':deepcopy(d.get('sharedRules',{}))})
